public boolean validateDelete()
{
    boolean ret = super();   
    if(ret)
    {
        if(this.salesLineExists())
        {
            ret = checkFailed("Cannot delete this record as it has already been referenced on one or more sales order lines");
        }
    }
    return ret;
}

    /// <summary>
    /// validateWrite
    /// </summary>
    /// <returns>Result</returns>
    public boolean validateWrite()
    {
        boolean ret = super();
        
        // date effectivity prompt

        if(this.ItemId == this.SubstituteItemId)
        {
            ret = checkFailed("Item and substitute item cannot be the same");
        }

        if(this.AccountCode == METSalesItemSubstitutionAccountCodeType::GroupId || 
            this.AccountCode == METSalesItemSubstitutionAccountCodeType::Table)
        {
            if(!this.AccountRelation)
            {
                ret = checkFailed(strFmt('%1 must be specified',
                    fieldPName(METSalesItemSubstitute, AccountRelation)));
            }
        }

        if(ret)
        {
            if(this.RecId && this.salesLineExists())
            {
                ret = checkFailed("Cannot modify this record as it has already been referenced on one or more sales order lines"); 
            }
        }
        return ret;
    }

/// <summary>
/// Check if this entry is already referenced on a sales order line.
/// </summary>
/// <returns>Result</returns>
public boolean salesLineExists()
{
    METSalesLine   metSalesLine;
    select firstonly metSalesLine
        where   metSalesLine.SubstitutionType           == METSalesItemSubstitutionType::SubstitutionCode
        &&      metSalesLine.SubstitutionSetupRefRecID  == this.RecId;
    return metSalesLine.RecID != 0;
}

/// <summary>
/// initValue
/// </summary>
public void initValue()
{
    super(); 
   
    this.SubstitutionCode = METSalesItemSubstitutionCode::Always;
    this.modifiedField(fieldNum(METSalesItemSubstitute, SubstitutionCode));
}

    /// <summary>
    /// modifiedField
    /// </summary>
    /// <param name = "_fieldId">_fieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        super(_fieldId);
        switch(_fieldId)
        {
            case fieldNum(METSalesItemSubstitute,AccountCode):
                if(this.AccountCode != METSalesItemSubstitutionAccountCodeType::All)
                {
                    this.AccountRelation = '';
                }
                break;

            case fieldNum(METSalesItemSubstitute, SubstitutionCode):
                if(this.SubstitutionCode == METSalesItemSubstitutionCode::Always)
                {
                    this.DateEffectivityCategory = 0;                     
                }
                else
                {
                    this.DateEffectivityCategory = 1;
                }
                break;
        }
    }

public Description description()
{
    return strFmt('%1, item %2, substitute item %3, valid from %4',
        this.SubstitutionCode,
        this.ItemId,
        this.SubstituteItemId,
        this.ValidFrom);
}
